"use client"

import { useState } from "react"
import ArrowLeft from "@/components/icons/ArrowLeft"
import PrimaryButton from "@/components/buttons/PrimaryButton"
import DeleteIcon from "@/components/icons/DeleteIcon"
import CheckIcon from "@/components/icons/CheckIcon"

type Props = {
  backHref: string
  nextHref: string
}

const MAX_VENDS = 4

export default function PrevConsCard({ backHref, nextHref }: Props) {
  const [input, setInput] = useState("")
  const [vends, setVends] = useState<string[]>([])
  const [firstVend, setFirstVend] = useState(false)

  const canAddMore = vends.length < MAX_VENDS
  const canContinue = firstVend || vends.length > 0

  function addVend() {
    const trimmed = input.trim()
    if (!trimmed || !canAddMore) return
    setVends((prev) => [...prev, trimmed])
    setInput("")
  }

  function removeVend(idx: number) {
    setVends((prev) => prev.filter((_, i) => i !== idx))
  }

  return (
    <div
      className="
        relative
        w-[914px] h-[579px]
        flex flex-col justify-between items-center
        px-[45px] py-[50px]
        bg-white rounded-[15px]
        shadow-[8px_8px_50px_rgba(0,0,0,0.05)]
        max-w-[calc(100vw-40px)]
      "
    >
      {/* Back Arrow */}
      <ArrowLeft href={backHref} className="absolute left-[45px] top-[50px]" />

      {/* Header */}
      <div className="w-full flex justify-center">
        <div className="relative w-[824px] h-[18px] flex items-start justify-center">
          <p className="m-0 font-inter text-[25px] leading-[30px] text-black text-center">
            Tell us where you’ve been!
          </p>
        </div>
      </div>

      {/* Content */}
      <div className="w-[436px] flex flex-col gap-[30px]">
        {/* Input */}
        <div className="flex flex-col gap-[8px]">
          <p className="font-inter text-[16px] text-[#1E1E1E]">
            Previous Vending
          </p>
          <p className="font-inter text-[12px] text-[#A5A5A5]">
            Max {MAX_VENDS} past vends
          </p>

          <div className="relative">
            <input
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && addVend()}
              placeholder="Vended Event 2026"
              className="
                w-full h-[40px]
                px-[12px]
                border border-[#A5A5A5]/50
                rounded-[8px]
                font-inter text-[14px]
                outline-none
              "
              disabled={!canAddMore}
            />
          </div>
        </div>

        {/* Checkbox */}
        <button
          type="button"
          onClick={() => setFirstVend((v) => !v)}
          className="flex items-center gap-[7px]"
        >
          {/* Visual checkbox */}
          <span
            className={[
              "relative w-[13px] h-[13px] rounded-[3.25px] flex-shrink-0",
              firstVend
                ? "bg-[#262626]"
                : "bg-white border border-[#262626]",
            ].join(" ")}
            aria-hidden="true"
          >
            {firstVend && (
              <span
                className="absolute"
                style={{
                  left: "2.17px",
                  top: "3.6px",
                  transform: "scale(0.78)",
                  transformOrigin: "top left",
                }}
              >
                <CheckIcon className="[&_path]:stroke-white" />
              </span>
            )}
          </span>

          <span className="font-inter text-[12px] text-[#A5A5A5]">
            I’m looking for my first vend.
          </span>
        </button>

        {/* Previous Vends List */}
        {vends.length > 0 && (
          <div className="flex flex-col gap-[15px]">
            <p className="text-center font-inter text-[13px] text-[#A5A5A5]">
              Previous Vends
            </p>

            {vends.map((vend, idx) => (
              <div
                key={idx}
                className="w-full flex items-center justify-center gap-[8px]"
              >
                <p className="font-inter text-[15px] text-[#262626] text-center">
                  {vend}
                </p>

                <button
                  type="button"
                  onClick={() => removeVend(idx)}
                  className="w-[16px] h-[16px] flex items-center justify-center"
                >
                  <DeleteIcon className="[&_path]:stroke-[#A5A5A5]" />
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Next */}
      <PrimaryButton
        href={canContinue ? nextHref : "#"}
        className={!canContinue ? "pointer-events-none opacity-40" : ""}
      >
        Next
      </PrimaryButton>
    </div>
  )
}
